/**
 * Slugs a workspace has renamed away from. Kept for `ORG_SLUG_HOLD_DAYS` days
 * after the rename so the old URL keeps resolving and nobody else can take
 * it; see `docs/adr/0005-workspace-urls.md`.
 */
export const organizationSlugRetirements = sqliteTable(
  "organization_slug_retirements",
  {
    slug: text("slug").primaryKey(),
    orgId: text("org_id").notNull(),
    retiredAt: text("retired_at").notNull(),
  },
  (table) => [index("organization_slug_retirements_org_idx").on(table.orgId)],
