import { and, eq, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizations,
  organizationSlugRetirements,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function isRetirementExpired(retiredAt: string, now: Date): boolean {
  const holdEndsAt = new Date(retiredAt).getTime() + ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
  return now.getTime() >= holdEndsAt;
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to a workspace the way every lookup must: the current
 * slug first, and — while its hold has not lapsed — a retired slug after
 * that. See `docs/adr/0005-workspace-urls.md` rule 3.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retirement = await findSlugRetirement(slug);
  if (!retirement || isRetirementExpired(retirement.retiredAt, new Date())) {
    return null;
  }

  return findOrgById(retirement.orgId as OrgId);
}

/** Raw retirement row, with no expiry filtering — callers decide what "expired" means. */
export async function findSlugRetirement(
  slug: string,
): Promise<{ orgId: string; retiredAt: string } | null> {
  const row = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .get();
  return row ? { orgId: row.orgId, retiredAt: row.retiredAt } : null;
}

/**
 * Whether `slug` may become `orgId`'s new slug: free of every other
 * workspace's current slug, and free of every other workspace's still-held
 * retirement. A workspace's own retired slug is always available to it.
 */
export async function isSlugAvailableForRename(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const holder = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (holder && holder.id !== orgId) return false;

  const retirement = await findSlugRetirement(slug);
  if (!retirement) return true;
  if (retirement.orgId === orgId) return true;

  return isRetirementExpired(retirement.retiredAt, new Date());
}

/** Retires `slug` for `orgId`, recording the instant it stopped being current. */
export async function retireOrgSlug(orgId: OrgId, slug: string): Promise<void> {
  getDb()
    .insert(organizationSlugRetirements)
    .values({ slug, orgId, retiredAt: toIsoTimestamp(new Date()) })
    .onConflictDoUpdate({
      target: organizationSlugRetirements.slug,
      set: { orgId, retiredAt: toIsoTimestamp(new Date()) },
    })
    .run();
}

/** Ends a retirement — used when a workspace renames back to a slug it once held. */
export async function unretireOrgSlug(slug: string): Promise<void> {
  getDb()
    .delete(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .run();
}

/**
 * Renames `orgId`'s slug, retiring the one it replaces and, when the new
 * slug is a retirement of this same workspace, ending that retirement.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  fromSlug: string,
  toSlug: string,
): Promise<Organization> {
  await unretireOrgSlug(toSlug);

  const row = getDb()
    .update(organizations)
    .set({ slug: toSlug, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();
  if (!row) throw new Error(`Organization ${orgId} not found`);

  await retireOrgSlug(orgId, fromSlug);

  return toOrganization(row);
}

