/**
 * Changes a workspace's URL slug. The same permission as any other settings
 * change guards it; a refusal changes nothing. Renaming to the current slug
 * is a no-op: nothing is written, nothing is published. Otherwise the old
 * slug is retired (it keeps resolving to this workspace for
 * `ORG_SLUG_HOLD_DAYS` days) and the event and audit action both fire once.
 * See `docs/adr/0005-workspace-urls.md`.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  assertValidSlug(input.slug);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) {
    return org;
  }

  const available = await orgRepo.isSlugAvailableForRename(input.slug, org.id);
  if (!available) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const updated = await orgRepo.renameOrgSlug(org.id, org.slug, input.slug);

  await emit("organization.slug_changed", {
    ...envelope(org.id, actor.userId),
    from: org.slug,
    to: input.slug,
  });

  return updated;
}

